import {MathScene} from './scene.js';
import {examples as baseExamples} from './examples.js';
import {newExamples} from './examples-v2.js';
import {DataWorkspace} from './data-workspace.js?v=2.0.2';
const examples=[...newExamples,...baseExamples];

const $=s=>document.querySelector(s);
const icons={table:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M9 3v18M3 15h18"/>',moon:'<path d="M20 14A9 9 0 0 1 10 3a9 9 0 1 0 10 11Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',layers:'<path d="m3 7 9-5 9 5-9 5z"/><path d="m3 12 9 5 9-5M3 17l9 5 9-5"/>',library:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><path d="M17 14v8m-4-4h8"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>',folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v12H3z"/><path d="M3 10h18"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor" stroke="none"/><circle cx="15" cy="17" r="3" fill="currentColor" stroke="none"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 3h.01"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 15v5h16v-5"/>',plus:'<path d="M12 4v16M4 12h16"/>',fit:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M8 8l8 8m0-8-8 8"/>',grid:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M9 3v18m6-18v18M3 9h18M3 15h18"/>',camera:'<path d="M8 6 9 3h6l1 3h5v14H3V6z"/><circle cx="12" cy="13" r="4"/>',wave:'<path d="M2 12c4-12 6 12 10 0s6 12 10 0"/>',rewind:'<path d="M4 5v6h6M5 10a8 8 0 1 1 1 9"/>',play:'<path d="m8 4 12 8-12 8z" fill="currentColor" stroke="none"/>',pause:'<path d="M7 4v16M17 4v16" stroke-width="4"/>',stop:'<rect x="5" y="5" width="14" height="14" rx="1" fill="currentColor" stroke="none"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12"/><circle cx="12" cy="12" r="3"/>',eyeoff:'<path d="m3 3 18 18M10 5c7-1 12 7 12 7s-2 4-6 6M7 6c-3 2-5 6-5 6s4 7 10 7c1 0 2 0 3-1"/>'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.code}</svg>`;}
function decorate(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{if(!el.querySelector('svg'))el.insertAdjacentHTML('afterbegin',icon(el.dataset.icon));});}decorate();
const editor=$('#code-editor'),highlight=$('#code-highlight'),numbers=$('#line-numbers');
const state={ready:false,busy:false,playing:false,time:0,params:{},objects:[],id:0,request:null,pending:null,ms:0,duration:4*Math.PI,dirty:false,restored:false};
let scene,dataWorkspace,sentDataRevision=-1,worker,timer,saveTimer,toastTimer,draft,selectedIndex=null,version='',lastFrame=performance.now(),cameraSaveTimer;
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function escapeHTML(s){return s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');}
function updateEditor(){
  const text=editor.value;let result='',last=0;
  const re=/(#[^\n]*|(?:f|r|b)?"(?:[^"\\\n]|\\.)*"|(?:f|r|b)?'(?:[^'\\\n]|\\.)*'|\b(?:from|import|def|return|lambda|for|in|if|else|elif|while|as|True|False|None|and|or|not|with|try|except|class|pass|break|continue|raise|yield|async|await)\b|\b\d+(?:\.\d*)?\b|\b(?:plot|surface|point|scatter|data|curve|vector|segment|polygon|param|print|integrate|derivative|sin|cos|sqrt|exp)\b)/g;
  for(const m of text.matchAll(re)){result+=escapeHTML(text.slice(last,m.index));const value=m[0],cls=value.startsWith('#')?'comment':/^[frb]?["']/.test(value)?'string':/^\d/.test(value)?'number':/^(plot|surface|point|scatter|data|curve|vector|segment|polygon|param|print|integrate|derivative|sin|cos|sqrt|exp)$/.test(value)?'function':'keyword';result+=`<span class="token-${cls}">${escapeHTML(value)}</span>`;last=m.index+value.length;}
  highlight.querySelector('code').innerHTML=result+escapeHTML(text.slice(last))+'\n';numbers.textContent=Array.from({length:text.split('\n').length},(_,i)=>i+1).join('\n');syncEditor();cursor();
}
function syncEditor(){highlight.scrollTop=editor.scrollTop;highlight.scrollLeft=editor.scrollLeft;numbers.scrollTop=editor.scrollTop;}
function cursor(){const s=editor.value.slice(0,editor.selectionStart).split('\n');$('#cursor-position').textContent=`Zeile ${s.length}, Spalte ${s.at(-1).length+1}`;}
function setCode(code){editor.value=code;updateEditor();}
editor.addEventListener('input',()=>{updateEditor();state.dirty=true;$('#save-status').textContent='Änderungen gespeichert';scheduleSave();});editor.addEventListener('scroll',syncEditor);editor.addEventListener('click',cursor);editor.addEventListener('keyup',cursor);
editor.addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const start=editor.selectionStart,end=editor.selectionEnd;editor.setRangeText('    ',start,end,'end');editor.dispatchEvent(new Event('input'));}else if(e.key==='Enter'&&!e.ctrlKey&&!e.metaKey){e.preventDefault();const start=editor.selectionStart,line=editor.value.slice(0,start).split('\n').at(-1);const indent=line.match(/^\s*/)[0]+(line.trimEnd().endsWith(':')?'    ':'');editor.setRangeText('\n'+indent,start,editor.selectionEnd,'end');editor.dispatchEvent(new Event('input'));}});
function rangeProgress(input){const progress=(Number(input.value)-Number(input.min))/(Number(input.max)-Number(input.min))*100;input.style.setProperty('--progress',progress+'%');}
function timeUI(){const slider=$('#time-slider');slider.value=state.time;rangeProgress(slider);$('#time-value').textContent=state.time.toFixed(2)+' s';}
function setDuration(d){state.duration=Math.min(10000,Math.max(.1,Number(d)||4*Math.PI));$('#time-slider').max=state.duration;$('#duration').value=state.duration;const ticks=$('.track-ticks');ticks.replaceChildren();for(let i=0;i<5;i++){const s=document.createElement('span');s.textContent=Math.abs(state.duration-4*Math.PI)<.001?(i===0?'0 s':i===1?'π':i+'π'):(state.duration*i/4).toFixed(1)+' s';ticks.append(s);}state.time=Math.min(state.duration,state.time);timeUI();}
function play(value=!state.playing){state.playing=value&&state.ready;$('#play-button').innerHTML=icon(state.playing?'pause':'play');$('#play-button').setAttribute('aria-label',state.playing?'Animation pausieren':'Animation starten');$('#animation-status').textContent=state.playing?'Deine Idee bewegt sich.':'Bereit, wenn du es bist.';lastFrame=performance.now();if(!state.playing)scheduleSave();}
function runtime(text,status='ready'){$('#runtime-status').replaceChildren();const dot=document.createElement('span');dot.className='status-dot '+(status==='loading'?'loading':status==='error'?'error':'');$('#runtime-status').append(dot,document.createTextNode(text));}
function consoleLog(text,error=false,label='Ausgabe'){
  if(!text?.trim())return;const root=$('#console-output');root.querySelector('.console-welcome')?.remove();const entry=document.createElement('div');entry.className='console-entry'+(error?' error':'');const runLabel=document.createElement('span');runLabel.className='run-label';runLabel.textContent=label;entry.append(runLabel,document.createTextNode(text.trim()));root.append(entry);while(root.children.length>60)root.firstElementChild.remove();root.scrollTop=root.scrollHeight;$('#console-count').textContent=root.children.length;
}
function setBusy(busy){state.busy=busy;$('#run-button').hidden=busy;$('#stop-button').hidden=!busy;$('#run-button').disabled=!state.ready;}
function run(reason='manual'){
  if(!state.ready){return;}const request={reason,code:editor.value,t:state.time,params:{...state.params}};
  if(state.busy){state.pending=request;return;}dispatch(request);
}
function dispatch(request){if(dataWorkspace&&sentDataRevision!==dataWorkspace.revision){worker.postMessage({type:'datasets',datasets:dataWorkspace.numeric()});sentDataRevision=dataWorkspace.revision;}state.request=request;state.busy=true;state.pending=null;setBusy(true);const id=++state.id;worker.postMessage({type:'run',id,...request});clearTimeout(timer);timer=setTimeout(()=>{if(state.busy){play(false);runtime('Berechnung läuft – bei Bedarf abbrechen','loading');$('#global-status').textContent='Python rechnet. „Abbrechen“ startet die Laufzeit neu.';}},7000);}
function createWorker(autoRun=true){
  sentDataRevision=-1;
  state.ready=false;state.busy=false;state.pending=null;$('#run-button').disabled=true;$('#play-button').disabled=true;$('#loading-overlay').hidden=false;$('#loading-overlay strong').textContent='Dein Mathelabor startet';$('#loading-text').textContent='Python wird im Browser geladen …';runtime('Python lädt …','loading');
  worker=new Worker(new URL('./python-worker.js',import.meta.url),{type:'module'});
  worker.onmessage=({data})=>{
    if(data.type==='status'){runtime(data.message,'loading');$('#loading-text').textContent=data.message;return;}
    if(data.type==='ready'){state.ready=true;version=data.version;runtime('Python '+version+' bereit');$('#run-button').disabled=false;$('#play-button').disabled=false;if(autoRun)run('initial');else{$('#loading-overlay').hidden=true;$('#global-status').textContent='Python neu gestartet. Code bei Bedarf anpassen und ausführen.';}return;}
    if(data.type==='init-error'){setBusy(false);play(false);runtime('Python konnte nicht starten','error');$('#loading-overlay').hidden=true;consoleLog(data.error+'\nPrüfe die Internetverbindung. Mit „Python neu starten“ kannst du es erneut versuchen.',true,'Start fehlgeschlagen');$('#run-button').disabled=false;$('#run-button').innerHTML=icon('rewind')+'Python neu starten';toast('Python-Download fehlgeschlagen. Details stehen in der Konsole.');return;}
    if(data.id!==state.id)return;clearTimeout(timer);const request=state.request;setBusy(false);$('#loading-overlay').hidden=true;state.ms=data.ms||0;
    if(data.type==='error'){play(false);state.pending=null;runtime('Fehler im Python-Code','error');consoleLog((data.stdout||'')+'\n'+data.error,true,'Python-Fehler · main.py');$('#global-status').textContent='Python-Fehler – die letzte gültige Szene bleibt sichtbar';return;}
    state.objects=data.objects;scene.update(data.objects);renderObjects();renderParameters(data.parameters);runtime('Python '+version+' bereit');$('#geometry-status').textContent=`${data.objects.length} Objekte · ${Math.round(data.ms)} ms`;
    if(request.reason!=='animation'&&request.reason!=='parameter'&&request.reason!=='scrub'){
      consoleLog(data.stdout,false,`${Math.round(data.ms)} ms · t = ${data.t.toFixed(2)} s`);consoleLog(data.stderr,true,'Python');if(!data.stdout?.trim()&&!data.stderr?.trim())consoleLog(`${data.objects.length} Objekte erzeugt.`,false,`${Math.round(data.ms)} ms`);
      state.dirty=false;$('#global-status').textContent='Alles läuft lokal in deinem Browser';scheduleSave();
    }
    if(request.reason==='example'||request.reason==='data'){scene.fit();scheduleSave();}
    if(request.reason==='initial'&&!state.restored)scene.fit();
    const pending=state.pending;state.pending=null;if(pending)dispatch(pending);
  };
  worker.onerror=e=>{clearTimeout(timer);state.ready=false;setBusy(false);play(false);$('#loading-overlay').hidden=true;runtime('Python-Worker unterbrochen','error');consoleLog(e.message,true);$('#run-button').disabled=false;$('#run-button').innerHTML=icon('rewind')+'Python neu starten';};
}
function stop(){clearTimeout(timer);worker?.terminate();play(false);state.id++;state.pending=null;setBusy(false);consoleLog('Ausführung abgebrochen. Python wird neu gestartet. Der Code wird erst auf deinen Klick wieder ausgeführt.',false,'Laufzeit');createWorker(false);}
function forgetDraftDataset(name){
  const key='raumwerk-draft-v2',saved=localStorage.getItem(key);
  if(saved){
    let stored;try{stored=JSON.parse(saved);}catch{localStorage.removeItem(key);}
    if(Array.isArray(stored?.datasets)){stored.datasets=stored.datasets.filter(d=>d.name!==name);localStorage.setItem(key,JSON.stringify(stored));}
  }
  if(Array.isArray(draft?.datasets))draft.datasets=draft.datasets.filter(d=>d.name!==name);
}
function datasetDeleted(name){
  clearTimeout(timer);worker?.terminate();play(false);state.id++;state.pending=null;state.request=null;setBusy(false);
  state.objects=[];scene.update([]);selectObject(null);$('#geometry-status').textContent='0 Objekte';
  $('#console-output').replaceChildren();$('#console-count').textContent='0';
  consoleLog('Datensatz „'+name+'“ gelöscht. Python-Speicher und Zeichnung wurden geleert. Dein Code bleibt erhalten; passe data('+JSON.stringify(name)+') vor dem Ausführen an.',false,'Daten');
  createWorker(false);
}
function renderObjects(){
  const root=$('#object-list');const key=state.objects.map(s=>s.name+'|'+s.kind+'|'+s.color).join(';');
  if(root.dataset.key===key&&key!==''){root.querySelectorAll('.object-equation').forEach((el,i)=>el.textContent=state.objects[i].description);return;}
  root.dataset.key=key;root.replaceChildren();$('#object-count').textContent=state.objects.length;
  if(!state.objects.length){const p=document.createElement('p');p.className='muted';p.textContent='Noch keine Geometrie. Nutze plot(), surface() oder point().';root.append(p);}
  state.objects.forEach((s,i)=>{const row=document.createElement('div');row.className='object-row';row.tabIndex=0;row.setAttribute('role','button');row.setAttribute('aria-label',s.name+' auswählen');row.classList.toggle('hidden-object',scene.hidden.has(s.name));row.classList.toggle('selected',selectedIndex===i);const dot=document.createElement('span');dot.className='object-dot';dot.style.setProperty('--object-color',/^#[0-9a-f]{3,8}$/i.test(s.color)?s.color:'#8870c9');const details=document.createElement('div');details.className='object-details';const title=document.createElement('div');title.className='object-name';title.textContent=s.name;const equation=document.createElement('div');equation.className='object-equation';equation.textContent=s.description;details.append(title,equation);const eye=document.createElement('button');eye.className='icon-button';eye.setAttribute('aria-label',s.name+(scene.hidden.has(s.name)?' einblenden':' ausblenden'));eye.innerHTML=icon(scene.hidden.has(s.name)?'eyeoff':'eye');eye.addEventListener('click',e=>{e.stopPropagation();scene.setHidden(s.name,!scene.hidden.has(s.name));root.dataset.key='';renderObjects();scheduleSave();});row.append(dot,details,eye);row.addEventListener('click',()=>selectObject(i));row.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();selectObject(i);}});root.append(row);});
}
function selectObject(i,point){selectedIndex=i;$('#object-list').dataset.key='';renderObjects();const el=$('#selection-info');el.hidden=i===null;if(i!==null&&state.objects[i]){el.textContent=state.objects[i].name+(point?' · ('+[point.x,point.y,point.z].map(x=>x.toFixed(3)).join(', ')+')':' · '+state.objects[i].description);}else el.hidden=true;}
function renderParameters(params){const root=$('#parameter-list');const signature=params.map(p=>[p.name,p.min,p.max,p.step].join('|')).join(';');const updated={};for(const p of params)updated[p.name]=p.value;state.params=updated;
  if(root.dataset.key===signature){params.forEach((p,i)=>{const input=root.querySelectorAll('input')[i];if(document.activeElement!==input)input.value=p.value;root.querySelectorAll('output')[i].textContent=formatNumber(p.value);rangeProgress(input);});return;}
  root.dataset.key=signature;root.replaceChildren();for(const p of params){const wrap=document.createElement('div');wrap.className='parameter';const label=document.createElement('label');label.className='parameter-title';const name=document.createElement('span');name.textContent=p.name;const output=document.createElement('output');output.textContent=formatNumber(p.value);label.append(name,output);const input=document.createElement('input');input.type='range';input.min=p.min;input.max=p.max;input.step=p.step;input.value=p.value;input.setAttribute('aria-label',p.name);input.addEventListener('input',()=>{state.params[p.name]=Number(input.value);output.textContent=formatNumber(Number(input.value));rangeProgress(input);run('parameter');scheduleSave();});rangeProgress(input);const limits=document.createElement('div');limits.className='range-limits';limits.innerHTML=`<span>${p.min}</span><span>${p.max}</span>`;wrap.append(label,input,limits);root.append(wrap);}
}
function formatNumber(n){return Number(n).toFixed(2);}
function setView(mode,plane='xy'){scene.view(mode,plane);syncView();scheduleSave();}
function syncView(){const is2=scene.mode==='2d';$('#view-2d').classList.toggle('active',is2);$('#view-3d').classList.toggle('active',!is2);$('#view-2d').setAttribute('aria-pressed',is2);$('#view-3d').setAttribute('aria-pressed',!is2);$('#scene-caption').textContent=is2?'XY-Ebene · Blick entlang der Z-Achse':'Interaktive 3D-Ansicht';$('#mouse-hint').textContent=is2?'Ziehen: verschieben · Scrollen: zoomen':'Ziehen: drehen · Rechts ziehen: verschieben · Scrollen: zoomen';// In 2D a normal left drag pans rather than trying to rotate.
  scene.controls.mouseButtons.LEFT=is2?2:0;
}
function projectData(includeDatasets=true){return{format:'raumwerk',version:2,...(includeDatasets?{datasets:dataWorkspace?.export()||[]}:{}),name:$('#project-name').value,code:editor.value,params:state.params,time:state.time,duration:state.duration,speed:Number($('#speed').value),view:scene.serialize(),savedAt:new Date().toISOString()};}
function scheduleSave(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{try{localStorage.setItem('raumwerk-project-v2',JSON.stringify(projectData(false)));$('#save-status').textContent='Lokal gespeichert';}catch{$('#save-status').textContent='Speicher voll – bitte exportieren';}},400);}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function saveProject(){download(JSON.stringify(projectData(),null,2),($('#project-name').value||'Raumwerk').replace(/[<>:"/\\|?*]/g,'-')+'.raumwerk.json','application/json');toast('Projekt als Datei gespeichert.');}
function applyProject(data){if(data?.format!=='raumwerk'||![1,2].includes(data.version)||typeof data.code!=='string'||data.code.length>500000)throw new Error('Keine gültige Raumwerk-Projektdatei (Version 1 oder 2).');if(data.params&&Object.values(data.params).some(v=>!Number.isFinite(v)))throw new Error('Ungültige Parameterwerte.');if(Array.isArray(data.datasets))dataWorkspace.replace(data.datasets);else if(data.version===1)dataWorkspace.replace([]);play(false);$('#project-name').value=String(data.name||'Mein Experiment').slice(0,80);setCode(data.code);state.params=data.params||{};state.time=Number.isFinite(data.time)?Math.max(0,data.time):0;setDuration(data.duration||4*Math.PI);if([.25,.5,1,2].includes(data.speed))$('#speed').value=data.speed;scene.restore(data.view);syncView();syncSettings();state.restored=true;selectedIndex=null;selectObject(null);timeUI();}
function loadExample(example){draft=projectData();try{localStorage.setItem('raumwerk-draft-v2',JSON.stringify(draft));}catch{}play(false);state.params={};state.time=0;scene.hidden.clear();$('#project-name').value=example.title;setCode(example.code);setView(example.view);setDuration(4*Math.PI);timeUI();$('#examples-dialog').close();selectedIndex=null;selectObject(null);run('example');scheduleSave();}
function exampleSVG(type){let content='';if(type==='wave'){for(let y=-4;y<=4;y+=.55){let points=[];for(let x=-5;x<=5;x+=.15){const z=1.7*Math.sin(Math.hypot(x,y)*1.4)*Math.exp(-.1*Math.hypot(x,y));points.push(`${150+x*19+y*9},${52+y*5-z*16}`);}content+=`<polyline points="${points.join(' ')}" fill="none" stroke="#947dc4" stroke-width="1" opacity=".7"/>`;}}
  else if(type==='helix'){for(let phase=0;phase<6;phase+=3.14159){let p=[];for(let u=0;u<19;u+=.1)p.push(`${90+u*6},${45+24*Math.sin(u+phase)}`);content+=`<polyline points="${p.join(' ')}" fill="none" stroke="${phase?'#73a991':'#a38ac7'}" stroke-width="2"/>`;}}
  else if(type==='quartz')content='<path d="m150 4 53 29v46l-53 23-53-23V33Z" fill="#a9c7e2" fill-opacity=".4" stroke="#83b9d1"/><path d="m150 4-19 34v43l19 21 18-26V35Z" fill="#aa9eda" fill-opacity=".4" stroke="#958bcb"/><path d="m97 33 34 5 37-3 35-2M97 79l34 2 37-5 35 3" fill="none" stroke="#87a6b8"/>';
  else if(type==='geometry')content='<path d="M75 73 155 9 229 72 146 93Z" fill="#a18acd" fill-opacity=".4" stroke="#8f79b3"/><path d="m75 73 80-64-9 84 83-21" fill="#9bbfa4" fill-opacity=".5" stroke="#75a58b"/>';
  else{const p=[];for(let u=-6;u<6;u+=.03){let x,y;if(type==='quantum'){x=65+(u+6)*15;y=70-45*Math.sin((u+6)*Math.PI/12)**2;}else if(type==='lissajous'){x=150+Math.sin(3*u)*90;y=50+Math.sin(2*u)*33;}else{x=150+u*20;y=type==='parabola'?80-(u*u)*3:50-Math.sin(u)*26;}p.push(`${x},${y}`);}content='<path d="M30 50h240M150 10v80" stroke="#d5deca"/>'+`<polyline points="${p.join(' ')}" fill="none" stroke="#a18ac7" stroke-width="2"/>`;}
  return `<svg viewBox="0 0 300 105" aria-hidden="true">${content}</svg>`;}
for(const example of examples){const card=document.createElement('button');card.className='example-card';card.innerHTML=`<div class="example-visual">${exampleSVG(example.visual)}</div><div class="example-copy"><span class="example-tag">${example.tag}</span><h3>${example.title}</h3><p>${example.description}</p></div>`;card.addEventListener('click',()=>loadExample(example));$('#examples-grid').append(card);}
function showDialog(id){$(id).showModal();}document.querySelectorAll('.close-dialog').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{const rect=d.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)d.close();}));
$('#help-button').onclick=$('#api-button').onclick=()=>showDialog('#help-dialog');$('#examples-button').onclick=()=>showDialog('#examples-dialog');$('#settings-button').onclick=()=>showDialog('#settings-dialog');
$('#restore-draft').onclick=()=>{try{const data=draft||JSON.parse(localStorage.getItem('raumwerk-draft-v2'));if(!data){toast('Es ist noch kein Entwurf hinterlegt.');return;}applyProject(data);$('#examples-dialog').close();run('manual');scheduleSave();}catch(e){toast(e.message);}};
$('#run-button').onclick=()=>{if(!state.ready){$('#run-button').innerHTML=icon('play')+'Ausführen <kbd>Ctrl ↵</kbd>';worker?.terminate();createWorker();}else run();};$('#stop-button').onclick=stop;
$('#play-button').onclick=()=>play();$('#reset-time').onclick=()=>{play(false);state.time=0;timeUI();run('scrub');scheduleSave();};$('#time-slider').addEventListener('input',()=>{play(false);state.time=Number($('#time-slider').value);timeUI();run('scrub');scheduleSave();});
$('#view-2d').onclick=()=>setView('2d');$('#view-3d').onclick=()=>setView('3d');$('#plane-xy').onclick=()=>setView('2d');$('#plane-xz').onclick=()=>setView('3d','xz');$('#plane-yz').onclick=()=>setView('3d','yz');$('#fit-button').onclick=()=>{scene.fit();scheduleSave();};
function syncSettings(){$('#show-grid').checked=scene.grid.visible;$('#show-axes').checked=scene.axes.visible;$('#show-wire').checked=scene.wires;$('#grid-button').classList.toggle('active',scene.grid.visible);$('#grid-button').setAttribute('aria-pressed',scene.grid.visible);}
$('#grid-button').onclick=()=>{scene.grid.visible=!scene.grid.visible;syncSettings();scheduleSave();};$('#show-grid').onchange=e=>{scene.grid.visible=e.target.checked;syncSettings();scheduleSave();};$('#show-axes').onchange=e=>{scene.axes.visible=e.target.checked;scheduleSave();};$('#show-wire').onchange=e=>{scene.setWire(e.target.checked);scheduleSave();};$('#duration').onchange=e=>{setDuration(e.target.value);scheduleSave();};$('#speed').onchange=scheduleSave;
$('#snapshot-button').onclick=()=>{scene.renderer.render(scene.scene,scene.camera);scene.renderer.domElement.toBlob(blob=>{if(blob)download(blob,($('#project-name').value||'Raumwerk')+'.png','image/png');});};
$('#save-button').onclick=saveProject;$('#project-name').oninput=scheduleSave;$('#import-button').onclick=()=>$('#project-file').click();$('#project-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>64e6)throw new Error('Die Projektdatei darf höchstens 64 MB groß sein.');const data=JSON.parse(await file.text());draft=projectData();applyProject(data);run('manual');scheduleSave();toast('Projekt geöffnet.');}catch(error){toast('Öffnen fehlgeschlagen: '+error.message);}finally{e.target.value='';}};
$('#clear-console').onclick=()=>{$('#console-output').replaceChildren();$('#console-count').textContent='0';};
$('#code-toggle').onclick=()=>{document.body.classList.toggle('editor-hidden');$('#code-toggle').classList.toggle('active',!document.body.classList.contains('editor-hidden'));};
$('#objects-tab').onclick=()=>{if(innerWidth<=980){$('.sidebar').classList.toggle('revealed');}else document.body.classList.toggle('sidebar-hidden');};
$('#add-button').onclick=()=>{const code='\n# Ein neues Objekt\nplot(lambda x: x**2 / 4, (-4, 4),\n     name="Parabel", color="#5e91bb")\n';editor.value+=code;updateEditor();editor.focus();editor.selectionStart=editor.selectionEnd=editor.value.length;editor.scrollTop=editor.scrollHeight;state.dirty=true;scheduleSave();toast('Parabel-Vorlage eingefügt. Mit Strg + Enter ausführen.');};
let resizing=false;$('#editor-resizer').onpointerdown=e=>{resizing=true;e.target.setPointerCapture(e.pointerId);document.body.style.userSelect='none';};$('#editor-resizer').onpointermove=e=>{if(resizing)document.documentElement.style.setProperty('--editor-width',Math.min(innerWidth*.6,Math.max(300,innerWidth-e.clientX))+'px');};$('#editor-resizer').onpointerup=()=>{resizing=false;document.body.style.userSelect='';};$('#editor-resizer').onkeydown=e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();const current=$('.editor-column').getBoundingClientRect().width;document.documentElement.style.setProperty('--editor-width',Math.max(300,current+(e.key==='ArrowLeft'?20:-20))+'px');}};
document.addEventListener('keydown',e=>{const typing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();run();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveProject();return;}if(typing||$('dialog[open]'))return;if(e.key==='2'){e.preventDefault();setView(scene.mode==='2d'?'3d':'2d');}else if(e.key.toLowerCase()==='f'){e.preventDefault();scene.fit();scheduleSave();}else if(e.code==='Space'){e.preventDefault();play();}});
function animate(now){const dt=Math.min(.1,(now-lastFrame)/1000);lastFrame=now;if(state.playing){state.time=(state.time+dt*Number($('#speed').value))%state.duration;timeUI();if(!state.busy)run('animation');}requestAnimationFrame(animate);}
document.addEventListener('visibilitychange',()=>{if(document.hidden)play(false);});

let themePreference;try{themePreference=localStorage.getItem('raumwerk-v2-theme')||'system';}catch{themePreference='system';}
const themeMedia=matchMedia('(prefers-color-scheme: dark)');
function applyTheme(){const dark=themePreference==='dark'||(themePreference==='system'&&themeMedia.matches);document.documentElement.dataset.theme=dark?'dark':'light';scene?.setTheme(dark);$('#theme-button').innerHTML=icon(dark?'sun':'moon');$('#theme-button').setAttribute('aria-label',dark?'Hellmodus einschalten':'Dunkelmodus einschalten');$('#theme-button').title=dark?'Hellmodus einschalten':'Dunkelmodus einschalten';$('#theme-select').value=themePreference;document.querySelector('meta[name="theme-color"]').content=dark?'#17212b':'#146451';}
function chooseTheme(value){themePreference=value;try{localStorage.setItem('raumwerk-v2-theme',value);}catch{}applyTheme();}
$('#theme-button').onclick=()=>chooseTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');$('#theme-select').onchange=e=>chooseTheme(e.target.value);themeMedia.addEventListener('change',()=>{if(themePreference==='system')applyTheme();});
$('#data-demo').onclick=async()=>{try{const r=await fetch('./demo-messdaten.xlsx');if(!r.ok)throw new Error('Beispieltabelle konnte nicht geladen werden.');dataWorkspace.openFile(new File([await r.blob()],'demo-messdaten.xlsx'));}catch(e){toast(e.message);}};

try{
  scene=new MathScene($('#viewport'),selectObject);scene.controls.addEventListener('end',()=>{clearTimeout(cameraSaveTimer);cameraSaveTimer=setTimeout(scheduleSave,400);});
  dataWorkspace=new DataWorkspace({toast,onOpen:()=>play(false),onChange:scheduleSave,onBeforeDelete:forgetDraftDataset,onDelete:datasetDeleted,onImport:(name,insert,dimensions)=>{if(insert){const code='\n# Excel-Datensatz: '+name+'\nimport numpy as np\npunkte = data('+JSON.stringify(name)+')\nscatter(punkte, name='+JSON.stringify(name)+', color="#67c6b1", size=5)\nprint("Datensatz '+name+':", punkte.shape)\n';editor.value+=code;updateEditor();setView(dimensions===3?'3d':'2d');run('data');}else{consoleLog('Datensatz '+name+' ist über data('+JSON.stringify(name)+') verfügbar.');}scheduleSave();}});
  await dataWorkspace.restore();applyTheme();
  let saved;try{saved=JSON.parse(localStorage.getItem('raumwerk-project-v2'));}catch{}
  if(saved){try{applyProject(saved);}catch{setCode(examples[0].code);}}else setCode(examples[0].code);
  syncView();syncSettings();timeUI();createWorker();requestAnimationFrame(animate);
}catch(error){$('#loading-overlay').hidden=false;$('#loading-overlay .spinner').hidden=true;$('#loading-overlay strong').textContent='3D-Ansicht nicht verfügbar';$('#loading-text').textContent='Bitte aktiviere Hardwarebeschleunigung oder verwende einen Browser mit WebGL2-Unterstützung. '+error.message;consoleLog(String(error),true,'Grafikfehler');}
// Read-only diagnostics for local regression checks and user troubleshooting.
window.raumwerk={get status(){return{ready:state.ready,busy:state.busy,objects:state.objects.length,time:state.time,playing:state.playing,mode:scene?.mode,params:{...state.params},datasets:dataWorkspace?.datasets.map(d=>({name:d.name,rows:d.values.length,dimensions:d.dimensions})),version:2};}};
